class KnowledgeLintFinding(Base):
    """Phát hiện của lượt rà soát với tập hành động cố định; bỏ qua cần lý do và ẩn 90 ngày (BR-166). Thêm 10/10/2026. Use case: UC-07-11."""

    __tablename__ = "knowledge_lint_finding"
    __table_args__ = ({"schema": "context"},)

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True, default=uuid7)
    org_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True))
    run_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("context.knowledge_run.id"), comment="FK knowledge_run"
    )
    data_space_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), comment="logic → org.data_space"
    )
    page_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("context.knowledge_page.id"),
        nullable=True,
        comment="FK knowledge_page; null với metric_without_page, undefined_term",
    )
    related_page_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("context.knowledge_page.id"),
        nullable=True,
        comment="FK knowledge_page; trang mâu thuẫn",
    )
    kind: Mapped[str] = mapped_column(
        Text,
        comment="contradiction, expired_claim, orphan_page, metric_without_page, undefined_term, source_decertified, stale_condition, policy_drift",
    )
    severity: Mapped[str] = mapped_column(Text, comment="low, medium, high")
    fingerprint: Mapped[str] = mapped_column(
        Text, comment="Mã băm loại và đối tượng; không báo lặp"
    )
    detail: Mapped[Any] = mapped_column(
        JSONB, server_default=sql_text("'{}'"), comment="Khẳng định, số, nguồn liên quan"
    )
    status: Mapped[str] = mapped_column(
        Text, server_default=sql_text("'open'"), comment="open, actioned, resolved, dismissed"
    )
    action: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
        comment="propose_edit, mark_stale, retire_page, create_page, dismiss, reassign",
    )
    action_reason: Mapped[str | None] = mapped_column(
        Text, nullable=True, comment="Bắt buộc khi dismiss"
    )
    page_version_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("context.knowledge_page_version.id"),
        nullable=True,
        comment="FK knowledge_page_version; bản nháp sửa khi propose_edit",
    )
    proposal_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True), nullable=True, comment="logic → inbox.proposal"
    )
    hitl_request_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → inbox.hitl_request (kind knowledge_finding)",
    )
    suppressed_until: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True, comment="Bỏ qua thì ẩn 90 ngày (BR-166)"
    )
    resolved_by: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True), nullable=True, comment="logic → org.app_user"
    )
    resolved_at: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), server_default=sql_text("now()")
    )


class DataProduct(Base):
    """Data product: phạm vi trả lời có cam kết của một Data Space, gồm câu hỏi trả lời được, dataset đã chuẩn hoá, chỉ số đã chứng nhận, owner và steward có tên, cam kết độ tươi và trạng thái (BR-175, ADR-42). Ví dụ POC: “Giá xăng dầu trong nước”. Khác pipeline.data_product của P06 (hợp đồng một bảng hoặc mart chia sẻ giữa Data Space); bảng này có thể chứa một sản phẩm P06 làm thành phần. Thêm 10/10/2026. Use case: UC-07-13, UC-07-14, UC-01-07, UC-01-01."""

    __tablename__ = "data_product"
    __table_args__ = ({"schema": "context"},)

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True, default=uuid7)
    org_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True))
    data_space_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), comment="logic → org.data_space"
    )
    code: Mapped[str] = mapped_column(
        Text, comment="Mã ngắn, không đổi sau khi active, ví dụ gia_xang_dau_trong_nuoc"
    )
    name: Mapped[str] = mapped_column(Text, comment="Ví dụ Giá xăng dầu trong nước")
    description: Mapped[str] = mapped_column(
        Text, comment="Phạm vi câu hỏi trả lời được, bằng lời; tối đa 2.000 ký tự"
    )
    sample_questions: Mapped[Any] = mapped_column(
        JSONB,
        server_default=sql_text("'[]'"),
        comment="Mảng {text, metric_code, period, expected}; tối thiểu 10 câu khi active, mỗi câu là một eval_item của eval_set_id",
    )
    scope_entities: Mapped[Any] = mapped_column(
        JSONB,
        server_default=sql_text("'[]'"),
        comment='Chiều và giá trị trong phạm vi, ví dụ [{"dimension":"mat_hang","values":["E5RON92","RON95-III","DO 0,05S-II"]}]; mảng rỗng là mọi giá trị của chiều hợp lệ',
    )
    period_grain: Mapped[str] = mapped_column(
        Text,
        comment="day, week, month, quarter, year, event (kỳ theo lịch sự kiện, ví dụ kỳ điều hành giá)",
    )
    period_from: Mapped[datetime.date] = mapped_column(
        Date, comment="Kỳ sớm nhất trả lời được, ví dụ 2024-01-01"
    )
    period_to: Mapped[datetime.date | None] = mapped_column(
        Date, nullable=True, comment="Null là đến hiện tại"
    )
    out_of_scope_note: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
        comment="Câu hỏi gần phạm vi nhưng không trả lời, ví dụ giá bán tại một cửa hàng cụ thể",
    )
    owner_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        comment="logic → org.app_user; người chịu trách nhiệm cam kết (data owner)",
    )
    steward_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        comment="logic → org.app_user; người giữ định nghĩa, xử lý Error Book; khác owner_id",
    )
    freshness_statement: Mapped[str] = mapped_column(
        Text,
        comment="Cam kết hiển thị cho người dùng, ví dụ “Giá xăng dầu trong nước: cập nhật trước 16:30 ngày điều hành”",
    )
    classification: Mapped[str] = mapped_column(
        Text,
        server_default=sql_text("'internal'"),
        comment="public, internal, confidential, restricted; mức cao nhất của các thành phần, trigger tính; dùng cho định tuyến mô hình (BR-180)",
    )
    eval_set_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → eval.eval_set (subject_type context) chứa câu hỏi mẫu và ca hồi quy Error Book",
    )
    pack_version_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → pack.pack_version nếu dựng từ mẫu của gói ngành",
    )
    version: Mapped[int] = mapped_column(
        Integer,
        server_default=sql_text("1"),
        comment="Tăng khi đổi phạm vi, thành phần primary hoặc cam kết sau khi active",
    )
    status: Mapped[str] = mapped_column(
        Text,
        server_default=sql_text("'draft'"),
        comment="draft, pending_review, active, suspended, retired",
    )
    suspended_reason: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
        comment="Bắt buộc khi suspended, ví dụ metric_decertified, dataset_decertified, manual",
    )
    proposal_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → inbox.proposal (kind data_product) đang chờ duyệt",
    )
    activated_by: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → org.app_user; người duyệt kích hoạt, khác created_by",
    )
    activated_at: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), server_default=sql_text("now()")
    )
    created_by: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True), nullable=True)
    updated_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), server_default=sql_text("now()")
    )
    updated_by: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True), nullable=True)


class DataProductMember(Base):
    """Thành phần của data product: dataset, chỉ số, trang tri thức, bộ sưu tập tài liệu, sản phẩm dữ liệu dùng chung của P06. Dataset primary mang cam kết độ tươi theo lịch và trạng thái độ tươi hiện tại cho cổng độ tươi (BR-178). Thêm 10/10/2026. Use case: UC-07-13, UC-01-07, UC-01-01."""

    __tablename__ = "data_product_member"
    __table_args__ = ({"schema": "context"},)

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True, default=uuid7)
    org_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True))
    data_product_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("context.data_product.id", ondelete="CASCADE"),
        comment="FK data_product",
    )
    member_kind: Mapped[str] = mapped_column(
        Text, comment="dataset, metric, knowledge_page, document_collection, shared_product"
    )
    member_ref: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        comment="logic → catalog.dataset, context.metric, context.knowledge_page, document.collection hoặc pipeline.data_product theo member_kind",
    )
    role: Mapped[str] = mapped_column(
        Text,
        server_default=sql_text("'primary'"),
        comment="primary, reference; chỉ số đọc từ dataset primary mới qua cổng độ tươi",
    )
    sla_kind: Mapped[str] = mapped_column(
        Text,
        server_default=sql_text("'none'"),
        comment="none, schedule, max_age; dataset primary phải khác none",
    )
    sla_cron: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
        comment="Lịch cập nhật cam kết theo giờ địa phương, cron 5 trường, ví dụ '30 16 * * 4' (16:30 thứ Năm, ngày điều hành giá xăng dầu)",
    )
    sla_event_calendar_code: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
        comment="logic → monitor.external_calendar.code cùng data_space_id (UNIQUE (data_space_id, code)); mã lịch sự kiện ngoài do P08 quản lý (ví dụ fuel_price_regulation, lịch điều hành giá xăng dầu); có thì hạn lấy theo lịch này, sla_cron chỉ cho giờ trong ngày",
    )
    sla_timezone: Mapped[str] = mapped_column(Text, server_default=sql_text("'Asia/Ho_Chi_Minh'"))
    sla_work_calendar_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → org.work_calendar; hạn rơi vào ngày nghỉ thì dời sang ngày làm việc kế tiếp",
    )
    sla_max_age: Mapped[datetime.timedelta | None] = mapped_column(
        Interval, nullable=True, comment="Với max_age: tuổi dữ liệu tối đa, ví dụ 1 day cho tỷ giá"
    )
    sla_grace: Mapped[datetime.timedelta] = mapped_column(
        Interval,
        server_default=sql_text("'0'"),
        comment="Ân hạn sau hạn trước khi che số, ví dụ 30 minutes; tối đa 1 ngày",
    )
    as_of_col: Mapped[str | None] = mapped_column(
        Text,
        nullable=True,
        comment="Cột ngày dữ liệu dùng đo độ tươi; null thì dùng catalog.dataset.business_date_col",
    )
    last_as_of: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
        comment="Ngày dữ liệu mới nhất đã có trong dataset; Connector hoặc Ingestion service cập nhật sau mỗi lượt nạp",
    )
    last_loaded_at: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True, comment="Thời điểm lượt nạp gần nhất xong"
    )
    expected_as_of: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
        comment="Ngày dữ liệu phải có theo hạn gần nhất đã qua",
    )
    next_due_at: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True, comment="Hạn kế tiếp tính từ lịch"
    )
    freshness_state: Mapped[str] = mapped_column(
        Text, server_default=sql_text("'unknown'"), comment="unknown, fresh, overdue, missing"
    )
    last_checked_at: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
    classification: Mapped[str] = mapped_column(
        Text,
        server_default=sql_text("'internal'"),
        comment="public, internal, confidential, restricted; với knowledge_page lấy từ trang; public chỉ khi dữ liệu là thông tin công bố (ví dụ giá điều hành của Bộ Công Thương) và có AC06 xác nhận; dùng cho định tuyến mô hình (BR-180)",
    )
    classification_confirmed_by: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        nullable=True,
        comment="logic → org.app_user (AC06); bắt buộc khi classification = public",
    )
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), server_default=sql_text("now()")
    )
    created_by: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True), nullable=True)
    updated_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), server_default=sql_text("now()")
    )
    updated_by: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True), nullable=True)


class Outbox(Base):
    """Events written in the same transaction as the change; Debezium publishes them (D5.3)."""

    __tablename__ = "outbox"
    __table_args__ = ({"schema": "context"},)

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True, default=uuid7)
    org_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True))
    aggregate_type: Mapped[str] = mapped_column(Text)
    aggregate_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True))
    event_type: Mapped[str] = mapped_column(Text)
    payload: Mapped[Any] = mapped_column(JSONB, server_default=sql_text("'{}'"))
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), server_default=sql_text("now()")
    )
    published_at: Mapped[datetime.datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
